import unittest

from reports.export import export_csv


class ExportCsvTests(unittest.TestCase):
    def test_header_and_rows(self):
        rows = [{"a": 1, "b": "x"}, {"a": 2, "b": "y"}]
        result = export_csv(rows, ["a", "b"])
        self.assertEqual(result, "a,b\r\n1,x\r\n2,y\r\n")

    def test_missing_and_none_fields(self):
        rows = [{"a": None}, {"b": 3}]
        result = export_csv(rows, ["a", "b"])
        self.assertEqual(result, "a,b\r\n,\r\n,3\r\n")

    def test_quoting_and_doubling(self):
        rows = [{"a": 'say "hi"', "b": "x,y", "c": "p\nq\r\nz"}]
        result = export_csv(rows, ["a", "b", "c"])
        self.assertEqual(
            result,
            'a,b,c\r\n"say ""hi""","x,y","p\nq\r\nz"\r\n',
        )

    def test_unicode_preserved(self):
        rows = [{"a": "héllo\u2603"}]
        result = export_csv(rows, ["a"])
        self.assertEqual(result, "a\r\nhéllo\u2603\r\n")

    def test_one_shot_generators(self):
        rows = ({"a": i} for i in range(2))
        cols = (c for c in ["a"])
        self.assertEqual(export_csv(rows, cols), "a\r\n0\r\n1\r\n")

    def test_empty_rows(self):
        self.assertEqual(export_csv([], ["a", "b"]), "a,b\r\n")

    def test_empty_columns(self):
        self.assertEqual(export_csv([{"a": 1}], []), "\r\n\r\n")

    def test_empty_rows_and_columns(self):
        self.assertEqual(export_csv([], []), "\r\n")

    def test_unselected_fields_ignored(self):
        rows = [{"a": 1, "b": 2, "c": 3}]
        self.assertEqual(export_csv(rows, ["c", "a"]), "c,a\r\n3,1\r\n")

    def test_non_string_values(self):
        rows = [{"a": 1.5, "b": True}]
        self.assertEqual(export_csv(rows, ["a", "b"]), "a,b\r\n1.5,True\r\n")

    def test_duplicate_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([], ["a", "a"])

    def test_non_string_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([], ["a", 1])

    def test_inputs_not_mutated(self):
        rows = [{"a": 1}]
        cols = ["a"]
        export_csv(rows, cols)
        self.assertEqual(rows, [{"a": 1}])
        self.assertEqual(cols, ["a"])


if __name__ == "__main__":
    unittest.main()

